                for pos in range(len(r) + 1):
                    nxt = depot if pos == len(r) else r[pos]
                    delta = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                    key = (delta, ri, pos)
                    if best_delta is None or key < best_delta:
                        best_delta = key
                        best_ri = ri
                        best_pos = pos
                    if pos < len(r):
                        prev = r[pos]
            if best_ri is None:
                routes.append([c])
            else:
                routes[best_ri].insert(best_pos, c)

    # Remove duplicates by keeping first occurrence, then reinsert any lost customers.
    used = {}
    cleaned = []
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if used.get(c, 0) == 0:
                nr.append(c)
                used[c] = 1
                load += demand_of(c)
        if nr:
            cleaned.append(nr)
    routes = cleaned

    present = {}
    for r in routes:
        for c in r:
            present[c] = 1
    missing = [c for c in customers if present.get(c, 0) == 0]
    for c in missing:
        dc = demand_of(c)
        best_ri = None
        best_pos = None
        best_key = None
        for ri in range(len(routes)):
            r = routes[ri]
            load = 0
            for x in r:
                load += demand_of(x)
            if load + dc > capacity:
                continue
            prev = depot
            for pos in range(len(r) + 1):
                nxt = depot if pos == len(r) else r[pos]
                delta = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                key = (delta, load, ri, pos)
                if best_key is None or key < best_key:
                    best_key = key
                    best_ri = ri
                    best_pos = pos
                if pos < len(r):
                    prev = r[pos]
        if best_ri is None:
            routes.append([c])
        else:
            routes[best_ri].insert(best_pos, c)

    # Final normalization: ensure all routes are non-empty and deterministic.
    final_routes = []
    for r in routes:
        if r:
            final_routes.append(r)

    return final_routes
